        o.step()
    return w.detach()

problems.solution:
def solve(initial, lr):
    w=nn.Parameter(torch.tensor(float(initial)))
    o=torch.optim.SGD([w],lr=lr)
    for _ in range(2):
        o.zero_grad()
        (w*w).backward()
        o.step()
    return w.detach()

